window.ISLAM={"quran":[{"id":"q-fatiha","n":1,"grp":"أُمُّ الْكِتَابِ","title":"سُورَةُ الْفَاتِحَةِ","gist":"نَحْمَدُ اللَّهَ رَبَّ الْعَالَمِينَ، وَنَعْبُدُهُ وَحْدَهُ وَنَسْتَعِينُ بِهِ، وَنَطْلُبُ مِنْهُ أَنْ يَهْدِيَنَا إِلَى الطَّرِيقِ الْمُسْتَقِيمِ.","ayat":["بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ","الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ","الرَّحْمَٰنِ الرَّحِيمِ","مَالِكِ يَوْمِ الدِّينِ","إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ"]},{"id":"q-87","n":87,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْأَعْلَى","gist":"نُسَبِّحُ اسْمَ رَبِّنَا الْأَعْلَى الَّذِي خَلَقَ فَسَوَّى وَقَدَّرَ فَهَدَى. وَقَدْ أَفْلَحَ مَنْ تَطَهَّرَ وَذَكَرَ اللَّهَ وَصَلَّى، وَالْآخِرَةُ خَيْرٌ وَأَبْقَى.","ayat":["سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى","الَّذِي خَلَقَ فَسَوَّىٰ","وَالَّذِي قَدَّرَ فَهَدَىٰ","وَالَّذِي أَخْرَجَ الْمَرْعَىٰ","فَجَعَلَهُ غُثَاءً أَحْوَىٰ","سَنُقْرِئُكَ فَلَا تَنسَىٰ","إِلَّا مَا شَاءَ اللَّهُ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ","وَنُيَسِّرُكَ لِلْيُسْرَىٰ","فَذَكِّرْ إِن نَّفَعَتِ الذِّكْرَىٰ","سَيَذَّكَّرُ مَن يَخْشَىٰ","وَيَتَجَنَّبُهَا الْأَشْقَى","الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ","ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","قَدْ أَفْلَحَ مَن تَزَكَّىٰ","وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ","بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا","وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ","إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ","صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ"]},{"id":"q-88","n":88,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْغَاشِيَةِ","gist":"تَصِفُ يَوْمَ الْقِيَامَةِ: وُجُوهٌ مُتْعَبَةٌ، وَوُجُوهٌ سَعِيدَةٌ فِي الْجَنَّةِ. وَتَدْعُونَا إِلَى النَّظَرِ فِي الْإِبِلِ وَالسَّمَاءِ وَالْجِبَالِ وَالْأَرْضِ لِنَعْرِفَ عَظَمَةَ اللَّهِ.","ayat":["هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ","وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ","عَامِلَةٌ نَّاصِبَةٌ","تَصْلَىٰ نَارًا حَامِيَةً","تُسْقَىٰ مِنْ عَيْنٍ آنِيَةٍ","لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ","لَّا يُسْمِنُ وَلَا يُغْنِي مِن جُوعٍ","وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ","لِّسَعْيِهَا رَاضِيَةٌ","فِي جَنَّةٍ عَالِيَةٍ","لَّا تَسْمَعُ فِيهَا لَاغِيَةً","فِيهَا عَيْنٌ جَارِيَةٌ","فِيهَا سُرُرٌ مَّرْفُوعَةٌ","وَأَكْوَابٌ مَّوْضُوعَةٌ","وَنَمَارِقُ مَصْفُوفَةٌ","وَزَرَابِيُّ مَبْثُوثَةٌ","أَفَلَا يَنظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ","وَإِلَى السَّمَاءِ كَيْفَ رُفِعَتْ","وَإِلَى الْجِبَالِ كَيْفَ نُصِبَتْ","وَإِلَى الْأَرْضِ كَيْفَ سُطِحَتْ","فَذَكِّرْ إِنَّمَا أَنتَ مُذَكِّرٌ","لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","فَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ","إِنَّ إِلَيْنَا إِيَابَهُمْ","ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم"]},{"id":"q-89","n":89,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْفَجْرِ","gist":"يُقْسِمُ اللَّهُ بِالْفَجْرِ، وَيَذْكُرُ مَا حَدَثَ لِأَقْوَامٍ طَغَوْا مِثْلِ عَادٍ وَثَمُودَ وَفِرْعَوْنَ. وَيَعِيبُ عَلَى مَنْ لَا يُكْرِمُ الْيَتِيمَ، وَيُنَادِي النَّفْسَ الْمُطْمَئِنَّةَ لِتَدْخُلَ الْجَنَّةَ.","ayat":["وَالْفَجْرِ","وَلَيَالٍ عَشْرٍ","وَالشَّفْعِ وَالْوَتْرِ","وَاللَّيْلِ إِذَا يَسْرِ","هَلْ فِي ذَٰلِكَ قَسَمٌ لِّذِي حِجْرٍ","أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","إِرَمَ ذَاتِ الْعِمَادِ","الَّتِي لَمْ يُخْلَقْ مِثْلُهَا فِي الْبِلَادِ","وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ","وَفِرْعَوْنَ ذِي الْأَوْتَادِ","الَّذِينَ طَغَوْا فِي الْبِلَادِ","فَأَكْثَرُوا فِيهَا الْفَسَادَ","فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","إِنَّ رَبَّكَ لَبِالْمِرْصَادِ","فَأَمَّا الْإِنسَانُ إِذَا مَا ابْتَلَاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ","وَأَمَّا إِذَا مَا ابْتَلَاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَنِ","كَلَّا بَل لَّا تُكْرِمُونَ الْيَتِيمَ","وَلَا تَحَاضُّونَ عَلَىٰ طَعَامِ الْمِسْكِينِ","وَتَأْكُلُونَ التُّرَاثَ أَكْلًا لَّمًّا","وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا","كَلَّا إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا","وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا","وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنسَانُ وَأَنَّىٰ لَهُ الذِّكْرَىٰ","يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي","فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُ أَحَدٌ","وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ","يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ","ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً","فَادْخُلِي فِي عِبَادِي","وَادْخُلِي جَنَّتِي"]},{"id":"q-90","n":90,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْبَلَدِ","gist":"يُقْسِمُ اللَّهُ بِمَكَّةَ، وَيُذَكِّرُنَا بِنِعَمِهِ عَلَيْنَا: الْعَيْنَيْنِ وَاللِّسَانَ وَالشَّفَتَيْنِ. وَمِنَ الْأَعْمَالِ الْعَظِيمَةِ عِتْقُ الرِّقَابِ، وَإِطْعَامُ الْجَائِعِ وَالْيَتِيمِ، وَالتَّوَاصِي بِالصَّبْرِ وَالرَّحْمَةِ.","ayat":["لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ","وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ","وَوَالِدٍ وَمَا وَلَدَ","لَقَدْ خَلَقْنَا الْإِنسَانَ فِي كَبَدٍ","أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ","يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا","أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ","أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ","وَلِسَانًا وَشَفَتَيْنِ","وَهَدَيْنَاهُ النَّجْدَيْنِ","فَلَا اقْتَحَمَ الْعَقَبَةَ","وَمَا أَدْرَاكَ مَا الْعَقَبَةُ","فَكُّ رَقَبَةٍ","أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ","يَتِيمًا ذَا مَقْرَبَةٍ","أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ","ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ","أُولَٰئِكَ أَصْحَابُ الْمَيْمَنَةِ","وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ","عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ"]},{"id":"q-91","n":91,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الشَّمْسِ","gist":"يُقْسِمُ اللَّهُ بِالشَّمْسِ وَالْقَمَرِ وَالنَّهَارِ وَاللَّيْلِ، ثُمَّ يُبَيِّنُ أَنَّ مَنْ طَهَّرَ نَفْسَهُ بِالطَّاعَةِ نَجَحَ، وَمَنْ أَفْسَدَهَا بِالْمَعْصِيَةِ خَسِرَ. وَيَذْكُرُ قَوْمَ ثَمُودَ الَّذِينَ كَذَّبُوا نَبِيَّهُمْ وَعَقَرُوا النَّاقَةَ.","ayat":["وَالشَّمْسِ وَضُحَاهَا","وَالْقَمَرِ إِذَا تَلَاهَا","وَالنَّهَارِ إِذَا جَلَّاهَا","وَاللَّيْلِ إِذَا يَغْشَاهَا","وَالسَّمَاءِ وَمَا بَنَاهَا","وَالْأَرْضِ وَمَا طَحَاهَا","وَنَفْسٍ وَمَا سَوَّاهَا","فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا","قَدْ أَفْلَحَ مَن زَكَّاهَا","وَقَدْ خَابَ مَن دَسَّاهَا","كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا","إِذِ انبَعَثَ أَشْقَاهَا","فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا","فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنبِهِمْ فَسَوَّاهَا","وَلَا يَخَافُ عُقْبَاهَا"]},{"id":"q-92","n":92,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ اللَّيْلِ","gist":"النَّاسُ يَسْعَوْنَ بِأَعْمَالٍ مُخْتَلِفَةٍ: فَمَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى يَسَّرَ اللَّهُ لَهُ طَرِيقَ الْخَيْرِ، وَمَنْ بَخِلَ وَكَذَّبَ يَسَّرَ لَهُ طَرِيقَ الشِّدَّةِ.","ayat":["وَاللَّيْلِ إِذَا يَغْشَىٰ","وَالنَّهَارِ إِذَا تَجَلَّىٰ","وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ","إِنَّ سَعْيَكُمْ لَشَتَّىٰ","فَأَمَّا مَنْ أَعْطَىٰ وَاتَّقَىٰ","وَصَدَّقَ بِالْحُسْنَىٰ","فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ","وَأَمَّا مَن بَخِلَ وَاسْتَغْنَىٰ","وَكَذَّبَ بِالْحُسْنَىٰ","فَسَنُيَسِّرُهُ لِلْعُسْرَىٰ","وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّىٰ","إِنَّ عَلَيْنَا لَلْهُدَىٰ","وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَىٰ","فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ","لَا يَصْلَاهَا إِلَّا الْأَشْقَى","الَّذِي كَذَّبَ وَتَوَلَّىٰ","وَسَيُجَنَّبُهَا الْأَتْقَى","الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّىٰ","وَمَا لِأَحَدٍ عِندَهُ مِن نِّعْمَةٍ تُجْزَىٰ","إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَىٰ","وَلَسَوْفَ يَرْضَىٰ"]},{"id":"q-93","n":93,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الضُّحَى","gist":"طَمْأَنَ اللَّهُ نَبِيَّهُ ﷺ بِأَنَّهُ لَمْ يَتْرُكْهُ وَلَمْ يَكْرَهْهُ، وَذَكَّرَهُ بِنِعَمِهِ: آوَاهُ يَتِيمًا، وَهَدَاهُ، وَأَغْنَاهُ. وَأَمَرَنَا أَلَّا نَقْهَرَ الْيَتِيمَ، وَلَا نَنْهَرَ السَّائِلَ، وَأَنْ نَتَحَدَّثَ بِنِعْمَةِ اللَّهِ.","ayat":["وَالضُّحَىٰ","وَاللَّيْلِ إِذَا سَجَىٰ","مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","وَلَلْآخِرَةُ خَيْرٌ لَّكَ مِنَ الْأُولَىٰ","وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ","أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ","وَوَجَدَكَ ضَالًّا فَهَدَىٰ","وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ","فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ","وَأَمَّا السَّائِلَ فَلَا تَنْهَرْ","وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ"]},{"id":"q-94","n":94,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الشَّرْحِ","gist":"أَنْعَمَ اللَّهُ عَلَى نَبِيِّهِ ﷺ فَشَرَحَ صَدْرَهُ وَوَضَعَ عَنْهُ وِزْرَهُ وَرَفَعَ ذِكْرَهُ. وَوَعَدَنَا أَنَّ مَعَ الْعُسْرِ يُسْرًا، فَإِذَا فَرَغْنَا مِنْ عَمَلٍ اجْتَهَدْنَا فِي عِبَادَةٍ وَرَغِبْنَا إِلَى رَبِّنَا.","ayat":["أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","وَوَضَعْنَا عَنكَ وِزْرَكَ","الَّذِي أَنقَضَ ظَهْرَكَ","وَرَفَعْنَا لَكَ ذِكْرَكَ","فَإِنَّ مَعَ الْعُسْرِ يُسْرًا","إِنَّ مَعَ الْعُسْرِ يُسْرًا","فَإِذَا فَرَغْتَ فَانصَبْ","وَإِلَىٰ رَبِّكَ فَارْغَب"]},{"id":"q-95","n":95,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ التِّينِ","gist":"يُقْسِمُ اللَّهُ بِالتِّينِ وَالزَّيْتُونِ وَطُورِ سِينِينَ وَالْبَلَدِ الْأَمِينِ، وَيُبَيِّنُ أَنَّهُ خَلَقَ الْإِنْسَانَ فِي أَحْسَنِ صُورَةٍ، وَأَنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَقْطُوعٍ.","ayat":["بِّسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ وَالتِّينِ وَالزَّيْتُونِ","وَطُورِ سِينِينَ","وَهَٰذَا الْبَلَدِ الْأَمِينِ","لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ","ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ","إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ","فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ","أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ"]},{"id":"q-96","n":96,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْعَلَقِ","gist":"هِيَ أَوَّلُ مَا نَزَلَ مِنَ الْقُرْآنِ: اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ. فَنَقْرَأُ وَنَتَعَلَّمُ بِاسْمِ اللَّهِ، وَاللَّهُ هُوَ الَّذِي عَلَّمَ الْإِنْسَانَ بِالْقَلَمِ مَا لَمْ يَعْلَمْ.","ayat":["اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ","خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ","اقْرَأْ وَرَبُّكَ الْأَكْرَمُ","الَّذِي عَلَّمَ بِالْقَلَمِ","عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ","كَلَّا إِنَّ الْإِنسَانَ لَيَطْغَىٰ","أَن رَّآهُ اسْتَغْنَىٰ","إِنَّ إِلَىٰ رَبِّكَ الرُّجْعَىٰ","أَرَأَيْتَ الَّذِي يَنْهَىٰ","عَبْدًا إِذَا صَلَّىٰ","أَرَأَيْتَ إِن كَانَ عَلَى الْهُدَىٰ","أَوْ أَمَرَ بِالتَّقْوَىٰ","أَرَأَيْتَ إِن كَذَّبَ وَتَوَلَّىٰ","أَلَمْ يَعْلَم بِأَنَّ اللَّهَ يَرَىٰ","كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًا بِالنَّاصِيَةِ","نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ","فَلْيَدْعُ نَادِيَهُ","سَنَدْعُ الزَّبَانِيَةَ","كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِب"]},{"id":"q-97","n":97,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْقَدْرِ","gist":"نَزَلَ الْقُرْآنُ فِي لَيْلَةِ الْقَدْرِ، وَهِيَ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ، تَنْزِلُ فِيهَا الْمَلَائِكَةُ، وَهِيَ سَلَامٌ حَتَّى طُلُوعِ الْفَجْرِ.","ayat":["بِّسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ","وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ","لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ","تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ","سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ"]},{"id":"q-98","n":98,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْبَيِّنَةِ","gist":"جَاءَ رَسُولٌ مِنَ اللَّهِ يَتْلُو صُحُفًا مُطَهَّرَةً. وَالْمَطْلُوبُ مِنَّا عِبَادَةُ اللَّهِ وَحْدَهُ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ، وَمَنْ آمَنَ وَعَمِلَ الصَّالِحَاتِ فَهُوَ خَيْرُ الْخَلْقِ وَجَزَاؤُهُ جَنَّاتُ عَدْنٍ.","ayat":["لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ","رَسُولٌ مِّنَ اللَّهِ يَتْلُو صُحُفًا مُّطَهَّرَةً","فِيهَا كُتُبٌ قَيِّمَةٌ","وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ","وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ وَذَٰلِكَ دِينُ الْقَيِّمَةِ","إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ","إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ","جَزَاؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ"]},{"id":"q-99","n":99,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الزَّلْزَلَةِ","gist":"فِي يَوْمِ الْقِيَامَةِ تَتَحَرَّكُ الْأَرْضُ حَرَكَةً عَظِيمَةً وَتُخْبِرُ بِمَا عُمِلَ عَلَيْهَا، وَيَرَى كُلُّ إِنْسَانٍ عَمَلَهُ: فَمَنْ عَمِلَ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ، وَمَنْ عَمِلَ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ.","ayat":["إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا","وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا","وَقَالَ الْإِنسَانُ مَا لَهَا","يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا","بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ","فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ","وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ"]},{"id":"q-100","n":100,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْعَادِيَاتِ","gist":"يُقْسِمُ اللَّهُ بِالْخَيْلِ الَّتِي تَجْرِي بِسُرْعَةٍ، ثُمَّ يُبَيِّنُ أَنَّ الْإِنْسَانَ جَحُودٌ لِنِعَمِ رَبِّهِ وَيُحِبُّ الْمَالَ حُبًّا شَدِيدًا، وَيُذَكِّرُهُ بِيَوْمٍ يُبْعَثُ فِيهِ مَنْ فِي الْقُبُورِ.","ayat":["وَالْعَادِيَاتِ ضَبْحًا","فَالْمُورِيَاتِ قَدْحًا","فَالْمُغِيرَاتِ صُبْحًا","فَأَثَرْنَ بِهِ نَقْعًا","فَوَسَطْنَ بِهِ جَمْعًا","إِنَّ الْإِنسَانَ لِرَبِّهِ لَكَنُودٌ","وَإِنَّهُ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ","وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ","أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ","وَحُصِّلَ مَا فِي الصُّدُورِ","إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ"]},{"id":"q-101","n":101,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْقَارِعَةِ","gist":"تَصِفُ يَوْمَ الْقِيَامَةِ الَّذِي تَقْرَعُ شِدَّتُهُ الْقُلُوبَ، فَيَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ، وَالْجِبَالُ كَالصُّوفِ الْمَنْفُوشِ. فَمَنْ ثَقُلَتْ مَوَازِينُهُ بِالْحَسَنَاتِ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ.","ayat":["الْقَارِعَةُ","مَا الْقَارِعَةُ","وَمَا أَدْرَاكَ مَا الْقَارِعَةُ","يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ","وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنفُوشِ","فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ","فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ","وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ","فَأُمُّهُ هَاوِيَةٌ","وَمَا أَدْرَاكَ مَا هِيَهْ","نَارٌ حَامِيَةٌ"]},{"id":"q-102","n":102,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ التَّكَاثُرِ","gist":"شَغَلَكُمُ التَّفَاخُرُ بِكَثْرَةِ الْمَالِ وَالْأَوْلَادِ حَتَّى جَاءَ الْمَوْتُ. فَلَا نَنْشَغِلْ بِالدُّنْيَا عَنِ الْآخِرَةِ، فَسَوْفَ نُسْأَلُ يَوْمَ الْقِيَامَةِ عَنِ النَّعِيمِ.","ayat":["أَلْهَاكُمُ التَّكَاثُرُ","حَتَّىٰ زُرْتُمُ الْمَقَابِرَ","كَلَّا سَوْفَ تَعْلَمُونَ","ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ","لَتَرَوُنَّ الْجَحِيمَ","ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ","ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ"]},{"id":"q-asr","n":103,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْعَصْرِ","gist":"الْإِنْسَانُ فِي خَسَارَةٍ إِلَّا مَنْ آمَنَ وَعَمِلَ الصَّالِحَاتِ وَأَوْصَى غَيْرَهُ بِالْحَقِّ وَبِالصَّبْرِ.","ayat":["وَالْعَصْرِ","إِنَّ الْإِنسَانَ لَفِي خُسْرٍ","إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ"]},{"id":"q-104","n":104,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْهُمَزَةِ","gist":"وَيْلٌ لِمَنْ يَعِيبُ النَّاسَ وَيَسْخَرُ مِنْهُمْ، وَيَجْمَعُ الْمَالَ وَيَظُنُّ أَنَّهُ يُخَلِّدُهُ. فَنَبْتَعِدُ عَنِ السُّخْرِيَةِ وَالْغِيبَةِ.","ayat":["وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ","الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ","يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ","كَلَّا لَيُنبَذَنَّ فِي الْحُطَمَةِ","وَمَا أَدْرَاكَ مَا الْحُطَمَةُ","نَارُ اللَّهِ الْمُوقَدَةُ","الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ","إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ","فِي عَمَدٍ مُّمَدَّدَةٍ"]},{"id":"q-105","n":105,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْفِيلِ","gist":"تَحْكِي قِصَّةَ أَبْرَهَةَ وَجَيْشِهِ الَّذِينَ جَاءُوا بِالْفِيَلَةِ لِيَهْدِمُوا الْكَعْبَةَ، فَأَرْسَلَ اللَّهُ عَلَيْهِمْ طَيْرًا أَبَابِيلَ تَرْمِيهِمْ بِحِجَارَةٍ، فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ.","ayat":["أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ","أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ","وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ","فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ"]},{"id":"q-106","n":106,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ قُرَيْشٍ","gist":"أَنْعَمَ اللَّهُ عَلَى قُرَيْشٍ بِرِحْلَةِ الشِّتَاءِ وَرِحْلَةِ الصَّيْفِ لِلتِّجَارَةِ، فَعَلَيْهِمْ أَنْ يَعْبُدُوا رَبَّ هَذَا الْبَيْتِ الَّذِي أَطْعَمَهُمْ مِنْ جُوعٍ وَآمَنَهُمْ مِنْ خَوْفٍ.","ayat":["لِإِيلَافِ قُرَيْشٍ","إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ","فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ","الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ"]},{"id":"q-107","n":107,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْمَاعُونِ","gist":"تَذُمُّ مَنْ يُكَذِّبُ بِيَوْمِ الدِّينِ، وَيَدْفَعُ الْيَتِيمَ بِقَسْوَةٍ، وَلَا يَحُثُّ عَلَى إِطْعَامِ الْمِسْكِينِ. وَتَذُمُّ الَّذِينَ يَغْفَلُونَ عَنْ صَلَاتِهِمْ وَيُرَاءُونَ وَيَمْنَعُونَ الْمَاعُونَ، أَيِ الْأَشْيَاءَ الصَّغِيرَةَ الَّتِي يَحْتَاجُهَا النَّاسُ.","ayat":["أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ","فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ","وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ","فَوَيْلٌ لِّلْمُصَلِّينَ","الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","الَّذِينَ هُمْ يُرَاءُونَ","وَيَمْنَعُونَ الْمَاعُونَ"]},{"id":"q-kawthar","n":108,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْكَوْثَرِ","gist":"أَعْطَى اللَّهُ نَبِيَّهُ ﷺ خَيْرًا كَثِيرًا، فَعَلَيْنَا أَنْ نَشْكُرَ اللَّهَ بِالصَّلَاةِ لَهُ.","ayat":["إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ","فَصَلِّ لِرَبِّكَ وَانْحَرْ","إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ"]},{"id":"q-109","n":109,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْكَافِرُونَ","gist":"نُعْلِنُ أَنَّنَا نَعْبُدُ اللَّهَ وَحْدَهُ، وَلَا نَعْبُدُ مَا يَعْبُدُهُ غَيْرُنَا. لَكُمْ دِينُكُمْ وَلِيَ دِينِ.","ayat":["قُلْ يَا أَيُّهَا الْكَافِرُونَ","لَا أَعْبُدُ مَا تَعْبُدُونَ","وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ","وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ","وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ","لَكُمْ دِينُكُمْ وَلِيَ دِينِ"]},{"id":"q-nasr","n":110,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ النَّصْرِ","gist":"إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ فَنُسَبِّحُ اللَّهَ وَنَحْمَدُهُ وَنَسْتَغْفِرُهُ، فَهُوَ كَثِيرُ التَّوْبَةِ عَلَى عِبَادِهِ.","ayat":["إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ","وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا","فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا"]},{"id":"q-111","n":111,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْمَسَدِ","gist":"أَبُو لَهَبٍ عَمُّ النَّبِيِّ ﷺ كَانَ يُؤْذِيهِ وَيُعَادِي دَعْوَتَهُ، فَخَسِرَ وَلَمْ يَنْفَعْهُ مَالُهُ، وَوُعِدَ بِنَارٍ ذَاتِ لَهَبٍ هُوَ وَامْرَأَتُهُ الَّتِي كَانَتْ تُؤْذِي النَّبِيَّ ﷺ.","ayat":["تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ","مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ","سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ","وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ","فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ"]},{"id":"q-ikhlas","n":112,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْإِخْلَاصِ","gist":"اللَّهُ وَاحِدٌ لَا شَرِيكَ لَهُ، يَحْتَاجُ إِلَيْهِ كُلُّ الْخَلْقِ وَهُوَ لَا يَحْتَاجُ إِلَى أَحَدٍ، لَيْسَ لَهُ وَالِدٌ وَلَا وَلَدٌ وَلَا يُشْبِهُهُ شَيْءٌ.","ayat":["قُلْ هُوَ اللَّهُ أَحَدٌ","اللَّهُ الصَّمَدُ","لَمْ يَلِدْ وَلَمْ يُولَدْ","وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ"]},{"id":"q-falaq","n":113,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ الْفَلَقِ","gist":"نَلْجَأُ إِلَى اللَّهِ وَحْدَهُ لِيَحْفَظَنَا مِنْ كُلِّ شَرٍّ.","ayat":["قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ","مِن شَرِّ مَا خَلَقَ","وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ","وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ"]},{"id":"q-nas","n":114,"grp":"حِزْبُ سَبِّحْ: الْحِزْبُ السِّتُّونَ","title":"سُورَةُ النَّاسِ","gist":"نَلْجَأُ إِلَى اللَّهِ رَبِّ النَّاسِ وَمَلِكِهِمْ وَإِلَهِهِمْ لِيَحْمِيَنَا مِنْ وَسْوَسَةِ الشَّيْطَانِ.","ayat":["قُلْ أَعُوذُ بِرَبِّ النَّاسِ","مَلِكِ النَّاسِ","إِلَٰهِ النَّاسِ","مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ","الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ","مِنَ الْجِنَّةِ وَالنَّاسِ"]}],"nawawi":[{"id":"n1","n":1,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"النِّيَّةُ","short":"الْأَعْمَالُ تُقْبَلُ بِحَسَبِ النِّيَّةِ","narr":"عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ:","text":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوْ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"ثَوَابُ أَعْمَالِنَا عَلَى حَسَبِ نِيَّتِنَا، فَنَنْوِي بِكُلِّ عَمَلٍ صَالِحٍ وَجْهَ اللَّهِ تَعَالَى. وَمَنْ هَاجَرَ لِلَّهِ وَرَسُولِهِ فَهِجْرَتُهُ لَهُمَا."},{"id":"n2","n":2,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْإِسْلَامُ وَالْإِيمَانُ وَالْإِحْسَانُ","short":"الْإِسْلَامُ وَالْإِيمَانُ وَالْإِحْسَانُ","narr":"عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ أَيْضًا قَالَ:","text":"بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللَّهِ ﷺ ذَاتَ يَوْمٍ، إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعْرِ، لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ. حَتَّى جَلَسَ إِلَى النَّبِيِّ ﷺ. فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ أَخْبِرْنِي عَنْ الْإِسْلَامِ. فَقَالَ رَسُولُ اللَّهِ ﷺ الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنْ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا. قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ! قَالَ: فَأَخْبِرْنِي عَنْ الْإِيمَانِ. قَالَ: أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ. قَالَ: صَدَقْتَ. قَالَ: فَأَخْبِرْنِي عَنْ الْإِحْسَانِ. قَالَ: أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ. قَالَ: فَأَخْبِرْنِي عَنْ السَّاعَةِ. قَالَ: مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ. قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا؟ قَالَ: أَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ. ثُمَّ انْطَلَقَ، فَلَبِثْتُ مَلِيًّا، ثُمَّ قَالَ: يَا عُمَرُ أَتَدْرِي مَنْ السَّائِلُ؟. ‫‬قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"جَاءَ جِبْرِيلُ عَلَيْهِ السَّلَامُ فِي صُورَةِ رَجُلٍ يُعَلِّمُ النَّاسَ دِينَهُمْ. فَالْإِسْلَامُ خَمْسَةُ أَرْكَانٍ، وَالْإِيمَانُ سِتَّةُ أَرْكَانٍ، وَالْإِحْسَانُ أَنْ نَعْبُدَ اللَّهَ كَأَنَّنَا نَرَاهُ، فَإِنْ لَمْ نَكُنْ نَرَاهُ فَهُوَ يَرَانَا."},{"id":"n3","n":3,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"أَرْكَانُ الْإِسْلَامِ","short":"بُنِيَ الْإِسْلَامُ عَلَى خَمْسَةِ أَرْكَانٍ","narr":"عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ:","text":"بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"الْإِسْلَامُ كَالْبَيْتِ لَهُ خَمْسَةُ أَعْمِدَةٍ: الشَّهَادَتَانِ، وَالصَّلَاةُ، وَالزَّكَاةُ، وَالْحَجُّ، وَصَوْمُ رَمَضَانَ."},{"id":"n4","n":4,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"خَلْقُ الْإِنْسَانِ","short":"اللَّهُ هُوَ الْخَالِقُ وَيَعْلَمُ كُلَّ شَيْءٍ","narr":"عَبْدُ اللَّهِ بْنُ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّهِ ﷺ -وَهُوَ الصَّادِقُ الْمَصْدُوقُ-:","text":"إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَشَقِيٍّ أَمْ سَعِيدٍ؛ فَوَاَللَّهِ الَّذِي لَا إِلَهَ غَيْرُهُ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا. وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"يُخْبِرُنَا النَّبِيُّ ﷺ بِمَرَاحِلِ خَلْقِ الْإِنْسَانِ فِي بَطْنِ أُمِّهِ، وَأَنَّ اللَّهَ يَعْلَمُ رِزْقَهُ وَأَجَلَهُ وَعَمَلَهُ. فَنُحْسِنُ الْعَمَلَ وَنَسْأَلُ اللَّهَ حُسْنَ الْخَاتِمَةِ."},{"id":"n5","n":5,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْعِبَادَةُ كَمَا عَلَّمَنَا النَّبِيُّ","short":"نَعْبُدُ اللَّهَ كَمَا عَلَّمَنَا رَسُولُهُ ﷺ","narr":"عَائِشَةُ أُمُّ الْمُؤْمِنِينَ رَضِيَ اللَّهُ عَنْهَا","intro":"عَنْ أُمِّ الْمُؤْمِنِينَ أُمِّ عَبْدِ اللَّهِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: قَالَ: رَسُولُ اللَّهِ ﷺ","text":"مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ وَفِي رِوَايَةٍ لِمُسْلِمٍ: مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"نَعْبُدُ اللَّهَ بِمَا شَرَعَهُ لَنَا فِي الْقُرْآنِ وَالسُّنَّةِ، وَمَنْ أَضَافَ إِلَى الدِّينِ شَيْئًا لَيْسَ مِنْهُ فَلَا يُقْبَلُ مِنْهُ."},{"id":"n6","n":6,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ","short":"نَبْتَعِدُ عَنِ الْأُمُورِ الْمُشْتَبِهَةِ","narr":"النُّعْمَانُ بْنُ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ أَبِي عَبْدِ اللَّهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ:","text":"إِنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنْ النَّاسِ، فَمَنْ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللَّهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"الْحَلَالُ وَاضِحٌ وَالْحَرَامُ وَاضِحٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَةٌ، فَمَنْ ابْتَعَدَ عَنْهَا حَفِظَ دِينَهُ. وَفِي الْجَسَدِ قِطْعَةٌ إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَهِيَ الْقَلْبُ."},{"id":"n7","n":7,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الدِّينُ النَّصِيحَةُ","short":"نَنْصَحُ لِلَّهِ وَلِرَسُولِهِ وَلِلنَّاسِ","narr":"تَمِيمٌ الدَّارِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ:","text":"الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"النَّصِيحَةُ أَنْ نُخْلِصَ لِلَّهِ، وَنُحِبَّ كِتَابَهُ وَنَتَّبِعَ رَسُولَهُ، وَنُرْشِدَ النَّاسَ إِلَى الْخَيْرِ بِرِفْقٍ وَصِدْقٍ."},{"id":"n8","n":8,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"حُرْمَةُ الْمُسْلِمِ","short":"دَمُ الْمُسْلِمِ وَمَالُهُ مُحْتَرَمَانِ","narr":"عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:","text":"أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ؛ فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللَّهِ تَعَالَى","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ حُفِظَ دَمُهُ وَمَالُهُ، وَاللَّهُ هُوَ الَّذِي يُحَاسِبُ عَلَى مَا فِي الْقُلُوبِ."},{"id":"n9","n":9,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"اتِّبَاعُ الْأَوَامِرِ وَالنَّوَاهِي","short":"نَتْرُكُ مَا نُهِينَا عَنْهُ وَنَفْعَلُ مَا نَسْتَطِيعُ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ:","text":"مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"مَا نَهَانَا عَنْهُ النَّبِيُّ ﷺ نَتْرُكُهُ كُلَّهُ، وَمَا أَمَرَنَا بِهِ نَفْعَلُ مِنْهُ مَا نَسْتَطِيعُ. وَنَبْتَعِدُ عَنْ كَثْرَةِ الْأَسْئِلَةِ الَّتِي لَا نَفْعَ فِيهَا."},{"id":"n10","n":10,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْكَسْبُ الْحَلَالُ","short":"اللَّهُ طَيِّبٌ لَا يَقْبَلُ إِلَّا الطَّيِّبَ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"إِنَّ اللَّهَ طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللَّهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ فَقَالَ تَعَالَى: «يَا أَيُّهَا الرُّسُلُ كُلُوا مِنْ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا»، وَقَالَ تَعَالَى: «يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ» ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ: يَا رَبِّ! يَا رَبِّ! وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِّيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لَهُ؟","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"نَأْكُلُ وَنَلْبَسُ وَنَتَصَدَّقُ مِنَ الْمَالِ الْحَلَالِ فَقَطْ، وَالدُّعَاءُ مَعَ أَكْلِ الْحَرَامِ بَعِيدٌ عَنِ الْإِجَابَةِ."},{"id":"n11","n":11,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"اتْرُكْ مَا يُشَكِّكُكَ","short":"نَتْرُكُ مَا نَشُكُّ فِيهِ","narr":"الْحَسَنُ بْنُ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ أَبِي مُحَمَّدٍ الْحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ سِبْطِ رَسُولِ اللَّهِ ﷺ وَرَيْحَانَتِهِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: حَفِظْتُ مِنْ رَسُولِ اللَّهِ ﷺ","text":"دَعْ مَا يُرِيبُكَ إِلَى مَا لَا يُرِيبُكَ","extra":"","src":"رَوَاهُ التِّرْمِذِيُّ وَالنَّسَائِيُّ","gist":"إِذَا شَكَكْنَا فِي أَمْرٍ هَلْ هُوَ جَائِزٌ أَمْ لَا، فَالْأَفْضَلُ أَنْ نَتْرُكَهُ وَنَفْعَلَ مَا نَطْمَئِنُّ إِلَيْهِ، فَالصِّدْقُ طُمَأْنِينَةٌ وَالْكَذِبُ شَكٌّ."},{"id":"n12","n":12,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"تَرْكُ مَا لَا يَعْنِينَا","short":"مِنْ حُسْنِ إِسْلَامِنَا أَنْ نَتْرُكَ مَا لَا يَعْنِينَا","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ","extra":"","src":"رَوَاهُ التِّرْمِذِيُّ وَغَيْرُهُ","gist":"نَشْتَغِلُ بِمَا يَنْفَعُنَا وَنَتْرُكُ التَّدَخُّلَ فِي شُؤُونِ غَيْرِنَا وَالْكَلَامَ الَّذِي لَا فَائِدَةَ فِيهِ."},{"id":"n13","n":13,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"حُبُّ الْخَيْرِ لِلْإِخْوَةِ","short":"نُحِبُّ لِغَيْرِنَا مَا نُحِبُّ لِأَنْفُسِنَا","narr":"أَنَسُ بْنُ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي حَمْزَةَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ خَادِمِ رَسُولِ اللَّهِ ﷺ عَنْ النَّبِيِّ ﷺ قَالَ:","text":"لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"الْمُؤْمِنُ يَفْرَحُ لِأَخِيهِ كَمَا يَفْرَحُ لِنَفْسِهِ، وَيُحِبُّ لَهُ الْخَيْرَ وَلَا يَحْسُدُهُ."},{"id":"n14","n":14,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"حُرْمَةُ دَمِ الْمُسْلِمِ","short":"دَمُ الْمُسْلِمِ عَظِيمُ الْحُرْمَةِ","narr":"عَبْدُ اللَّهِ بْنُ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"لَا يَجُوزُ الِاعْتِدَاءُ عَلَى أَحَدٍ، فَدَمُ الْمُسْلِمِ عَظِيمُ الْحُرْمَةِ. وَالْعُقُوبَاتُ الشَّرْعِيَّةُ لَا يُقِيمُهَا إِلَّا الْحَاكِمُ وَالْقَضَاءُ، وَلَيْسَ لِأَيِّ إِنْسَانٍ أَنْ يَفْعَلَهَا بِنَفْسِهِ."},{"id":"n15","n":15,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْإِحْسَانُ إِلَى الْجَارِ وَالضَّيْفِ","short":"نُكْرِمُ الْجَارَ وَالضَّيْفَ وَنَقُولُ خَيْرًا","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:","text":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"مِنْ عَلَامَاتِ الْإِيمَانِ أَنْ نَقُولَ خَيْرًا أَوْ نَسْكُتَ، وَأَنْ نُكْرِمَ جَارَنَا وَضَيْفَنَا."},{"id":"n16","n":16,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"لَا تَغْضَبْ","short":"نَضْبِطُ أَنْفُسَنَا عِنْدَ الْغَضَبِ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ﷺ أَوْصِنِي.","text":"قَالَ: لَا تَغْضَبْ، فَرَدَّدَ مِرَارًا، قَالَ: لَا تَغْضَبْ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ","gist":"جَاءَ رَجُلٌ يَطْلُبُ وَصِيَّةً فَكَرَّرَ النَّبِيُّ ﷺ: لَا تَغْضَبْ. فَإِذَا غَضِبْنَا نَصْبِرُ وَنَهْدَأُ وَلَا نُؤْذِي أَحَدًا."},{"id":"n17","n":17,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْإِحْسَانُ فِي كُلِّ شَيْءٍ","short":"نُتْقِنُ أَعْمَالَنَا وَنُحْسِنُ إِلَى كُلِّ شَيْءٍ","narr":"شَدَّادُ بْنُ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ قَالَ:","text":"إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"كَتَبَ اللَّهُ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَنُحْسِنُ فِي عَمَلِنَا وَمُعَامَلَتِنَا، وَنَرْفُقُ بِالْحَيَوَانِ."},{"id":"n18","n":18,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ","short":"نَتَّقِي اللَّهَ فِي كُلِّ مَكَانٍ","narr":"أَبُو ذَرٍّ وَمُعَاذُ بْنُ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ، وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ ﷺ قَالَ:","text":"اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعْ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقْ النَّاسَ بِخُلُقٍ حَسَنٍ","extra":"","src":"رَوَاهُ التِّرْمِذِيُّ","gist":"نَخَافُ اللَّهَ فِي السِّرِّ وَالْعَلَنِ، وَإِذَا أَخْطَأْنَا فَعَلْنَا حَسَنَةً تَمْحُو الْخَطَأَ، وَنُعَامِلُ النَّاسَ بِخُلُقٍ حَسَنٍ."},{"id":"n19","n":19,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"احْفَظِ اللَّهَ يَحْفَظْكَ","short":"مَنْ حَفِظَ اللَّهَ حَفِظَهُ اللَّهُ","narr":"عَبْدُ اللَّهِ بْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:","text":"كُنْتُ خَلْفَ رَسُولِ اللَّهِ ﷺ يَوْمًا، فَقَالَ: يَا غُلَامِ! إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظْ اللَّهَ يَحْفَظْكَ، احْفَظْ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلْ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ، وَاعْلَمْ أَنَّ الْأُمَّةَ لَوْ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ، وَإِنْ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ؛ رُفِعَتْ الْأَقْلَامُ، وَجَفَّتْ الصُّحُفُ","extra":"وَفِي رِوَايَةٍ أُخْرَى: احْفَظْ اللَّهَ تَجِدْهُ أَمَامَكَ، تَعَرَّفْ إِلَى اللَّهِ فِي الرَّخَاءِ يَعْرِفُكَ فِي الشِّدَّةِ، وَاعْلَمْ أَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَمَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ، وَأَنْ الْفَرَجَ مَعَ الْكَرْبِ، وَأَنَّ مَعَ الْعُسْرِ يُسْرًا","src":"رَوَاهُ التِّرْمِذِيُّ","gist":"نَحْفَظُ أَوَامِرَ اللَّهِ فَيَحْفَظُنَا. وَإِذَا سَأَلْنَا نَسْأَلُ اللَّهَ، وَإِذَا احْتَجْنَا إِلَى الْعَوْنِ نَسْتَعِينُ بِاللَّهِ، وَنَعْلَمُ أَنَّ مَا كَتَبَهُ اللَّهُ لَنَا سَيَصِلُ إِلَيْنَا."},{"id":"n20","n":20,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْحَيَاءُ","short":"الْحَيَاءُ خُلُقٌ يَمْنَعُنَا مِنَ الْقَبِيحِ","narr":"أَبُو مَسْعُودٍ الْأَنْصَارِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الْأَنْصَارِيِّ الْبَدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ","gist":"الْحَيَاءُ يَمْنَعُنَا مِنْ فِعْلِ الْقَبِيحِ. وَمَنْ فَقَدَ الْحَيَاءَ فَعَلَ مَا يَشَاءُ دُونَ خَجَلٍ، وَهَذَا تَحْذِيرٌ لَا إِذْنٌ."},{"id":"n21","n":21,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الِاسْتِقَامَةُ","short":"نُؤْمِنُ بِاللَّهِ ثُمَّ نَسْتَقِيمُ","narr":"سُفْيَانُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي عَمْرٍو وَقِيلَ: أَبِي عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ:","text":"قُلْتُ: يَا رَسُولَ اللَّهِ! قُلْ لِي فِي الْإِسْلَامِ قَوْلًا لَا أَسْأَلُ عَنْهُ أَحَدًا غَيْرَكَ؛ قَالَ: قُلْ: آمَنْتُ بِاللَّهِ ثُمَّ اسْتَقِمْ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"نُؤْمِنُ بِاللَّهِ ثُمَّ نَثْبُتُ عَلَى طَاعَتِهِ وَلَا نَنْحَرِفُ عَنْهَا."},{"id":"n22","n":22,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الطَّرِيقُ إِلَى الْجَنَّةِ","short":"نُؤَدِّي الْفَرَائِضَ وَنَجْتَنِبُ الْحَرَامَ","narr":"جَابِرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا:","text":"أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ﷺ فَقَالَ: أَرَأَيْتَ إِذَا صَلَّيْتُ الْمَكْتُوبَاتِ، وَصُمْتُ رَمَضَانَ، وَأَحْلَلْتُ الْحَلَالَ، وَحَرَّمْتُ الْحَرَامَ، وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا؛ أَأَدْخُلُ الْجَنَّةَ؟ قَالَ: نَعَمْ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"مَنْ صَلَّى الصَّلَوَاتِ الْخَمْسَ، وَصَامَ رَمَضَانَ، وَأَحَلَّ الْحَلَالَ، وَحَرَّمَ الْحَرَامَ دَخَلَ الْجَنَّةَ بِإِذْنِ اللَّهِ."},{"id":"n23","n":23,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الطَّهَارَةُ وَالْأَعْمَالُ الصَّالِحَةُ","short":"الطَّهُورُ شَطْرُ الْإِيمَانِ","narr":"أَبُو مَالِكٍ الْأَشْعَرِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي مَالِكٍ الْحَارِثِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"الطَّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآنِ -أَوْ: تَمْلَأُ- مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"الطَّهَارَةُ نِصْفُ الْإِيمَانِ، وَالْحَمْدُ لِلَّهِ وَالتَّسْبِيحُ وَالصَّلَاةُ وَالصَّبْرُ كُلُّهَا نُورٌ وَخَيْرٌ، وَكُلُّ إِنْسَانٍ يَسْعَى إِمَّا لِنَجَاةِ نَفْسِهِ أَوْ لِهَلَاكِهَا."},{"id":"n24","n":24,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"تَحْرِيمُ الظُّلْمِ","short":"اللَّهُ حَرَّمَ الظُّلْمَ فَلَا نَظْلِمُ أَحَدًا","narr":"أَبُو ذَرٍّ الْغِفَارِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ رَضِيَ اللَّهُ عَنْهُ عَنْ النَّبِيِّ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، أَنَّهُ قَالَ:","text":"يَا عِبَادِي: إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا؛ فَلَا تَظَالَمُوا. يَا عِبَادِي! كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ، فَاسْتَهْدُونِي أَهْدِكُمْ. يَا عِبَادِي! كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ. يَا عِبَادِي! كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ. يَا عِبَادِي! إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا؛ فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ. يَا عِبَادِي! إِنَّكُمْ لَنْ تَبْلُغُوا ضُرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا. يَا عِبَادِي! لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ، فَسَأَلُونِي، فَأَعْطَيْتُ كُلَّ وَاحِدٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ. يَا عِبَادِي! إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا؛ فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدْ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"هَذَا حَدِيثٌ قُدْسِيٌّ يَرْوِيهِ النَّبِيُّ ﷺ عَنْ رَبِّهِ: اللَّهُ حَرَّمَ الظُّلْمَ، وَنَحْنُ كُلُّنَا نَحْتَاجُ إِلَى هِدَايَتِهِ وَرِزْقِهِ وَمَغْفِرَتِهِ، فَلْنَسْأَلْهُ وَلَا نَظْلِمْ."},{"id":"n25","n":25,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"أَبْوَابُ الصَّدَقَةِ","short":"أَعْمَالُ الْخَيْرِ كُلُّهَا صَدَقَةٌ","narr":"أَبُو ذَرٍّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ أَيْضًا،","text":"أَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ ﷺ قَالُوا لِلنَّبِيِّ ﷺ يَا رَسُولَ اللَّهِ ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ؛ يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ. قَالَ: أَوَلَيْسَ قَدْ جَعَلَ اللَّهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِمَعْرُوفٍ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إِذَا وَضَعَهَا فِي الْحَلَالِ، كَانَ لَهُ أَجْرٌ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"الصَّدَقَةُ لَيْسَتْ بِالْمَالِ فَقَطْ؛ التَّسْبِيحُ وَالْحَمْدُ وَالْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ وَمُسَاعَدَةُ النَّاسِ كُلُّهَا صَدَقَةٌ."},{"id":"n26","n":26,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الصَّدَقَةُ كُلَّ يَوْمٍ","short":"الْعَدْلُ وَالْإِعَانَةُ وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"كُلُّ سُلَامَى مِنْ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إِلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنْ الطَّرِيقِ صَدَقَةٌ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"فِي كُلِّ يَوْمٍ نَسْتَطِيعُ أَنْ نَتَصَدَّقَ: نُعِينُ إِنْسَانًا، وَنَقُولُ كَلِمَةً طَيِّبَةً، وَنَمْشِي إِلَى الصَّلَاةِ، وَنُزِيلُ الْأَذَى مِنَ الطَّرِيقِ."},{"id":"n27","n":27,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْبِرُّ حُسْنُ الْخُلُقِ","short":"الْبِرُّ هُوَ حُسْنُ الْخُلُقِ","narr":"النَّوَّاسُ بْنُ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ عَنْ النَّبِيِّ ﷺ قَالَ:","text":"الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِكَ، وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ","extra":"وَعَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ ﷺ فَقَالَ: جِئْتَ تَسْأَلُ عَنْ الْبِرِّ؟ قُلْتُ: نَعَمْ. فقَالَ: اسْتَفْتِ قَلْبَكَ، الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ، وَاطْمَأَنَّ إِلَيْهِ الْقَلْبُ، وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ","src":"رَوَاهُ مُسْلِمٌ، وَحَدِيثُ وَابِصَةَ رَوَاهُ أَحْمَدُ وَالدَّارِمِيُّ","gist":"الْخُلُقُ الْحَسَنُ مِنْ أَعْظَمِ الْبِرِّ، وَالْإِثْمُ مَا شَعَرْنَا بِالضِّيقِ مِنْهُ فِي قُلُوبِنَا وَكَرِهْنَا أَنْ يَرَانَا النَّاسُ عَلَيْهِ."},{"id":"n28","n":28,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"السُّنَّةُ وَالطَّاعَةُ","short":"نَتَمَسَّكُ بِسُنَّةِ النَّبِيِّ ﷺ","narr":"الْعِرْبَاضُ بْنُ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي نَجِيحٍ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ:","text":"وَعَظَنَا رَسُولُ اللَّهِ ﷺ مَوْعِظَةً وَجِلَتْ مِنْهَا الْقُلُوبُ، وَذَرَفَتْ مِنْهَا الْعُيُونُ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا، قَالَ: أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ؛ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ","extra":"","src":"رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ","gist":"يُوصِينَا النَّبِيُّ ﷺ بِتَقْوَى اللَّهِ وَطَاعَةِ وُلَاةِ الْأَمْرِ فِي الْخَيْرِ، وَبِالتَّمَسُّكِ بِسُنَّتِهِ وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ."},{"id":"n29","n":29,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"أَبْوَابُ الْخَيْرِ","short":"رَأْسُ الْأَمْرِ الْإِسْلَامُ وَعَمُودُهُ الصَّلَاةُ","narr":"مُعَاذُ بْنُ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ! أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ وَيُبَاعِدْنِي مِنْ النَّارِ، قَالَ:","text":"لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ عَلَيْهِ: تَعْبُدُ اللَّهَ لَا تُشْرِكْ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ، ثُمَّ قَالَ: أَلَا أَدُلُّكَ عَلَى أَبْوَابِ الْخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ، ثُمَّ تَلَا: « تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ » حَتَّى بَلَغَ «يَعْمَلُونَ»، ثُمَّ قَالَ: أَلَا أُخْبِرُكَ بِرَأْسِ الْأَمْرِ وَعَمُودِهِ وَذُرْوَةِ سَنَامِهِ؟ قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذُرْوَةُ سَنَامِهِ الْجِهَادُ، ثُمَّ قَالَ: أَلَا أُخْبِرُكَ بِمَلَاكِ ذَلِكَ كُلِّهِ؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ! فَأَخَذَ بِلِسَانِهِ وَقَالَ: كُفَّ عَلَيْكَ هَذَا. قُلْتُ: يَا نَبِيَّ اللَّهِ وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ؟ فَقَالَ: ثَكِلَتْكَ أُمُّكَ وَهَلْ يَكُبُّ النَّاسَ عَلَى وُجُوهِهِمْ -أَوْ قَالَ عَلَى مَنَاخِرِهِمْ- إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ؟!","extra":"","src":"رَوَاهُ التِّرْمِذِيُّ","gist":"الْإِسْلَامُ رَأْسُ الْأَمْرِ، وَالصَّلَاةُ عَمُودُهُ، وَالْجِهَادُ ذِرْوَةُ سَنَامِهِ. وَأَهَمُّ مَا نَحْفَظُهُ أَنْ نَمْلِكَ أَلْسِنَتَنَا فَلَا نَقُولَ إِلَّا خَيْرًا."},{"id":"n30","n":30,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"حُدُودُ اللَّهِ","short":"نَلْتَزِمُ بِمَا فَرَضَهُ اللَّهُ وَنَبْتَعِدُ عَمَّا حَرَّمَهُ","narr":"أَبُو ثَعْلَبَةَ الْخُشَنِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُومِ بْنِ نَاشِرٍ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ قَالَ:","text":"إِنَّ اللَّهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا","extra":"","src":"رَوَاهُ الدَّارَقُطْنِيُّ وَغَيْرُهُ","gist":"اللَّهُ فَرَضَ فَرَائِضَ فَلَا نُضَيِّعُهَا، وَحَرَّمَ أَشْيَاءَ فَلَا نَقْتَرِبُ مِنْهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً بِنَا فَلَا نَبْحَثُ عَنْهَا."},{"id":"n31","n":31,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الزُّهْدُ فِي الدُّنْيَا","short":"لَا نَتَعَلَّقُ بِالدُّنْيَا وَلَا بِمَا فِي أَيْدِي النَّاسِ","narr":"سَهْلُ بْنُ سَعْدٍ السَّاعِدِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي الْعَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيّ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: يَا رَسُولَ اللَّهِ! دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ أَحَبَّنِي اللَّهُ وَأَحَبَّنِي النَّاسُ؛ فَقَالَ:","text":"ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللَّهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّكَ النَّاسُ","extra":"","src":"رَوَاهُ ابْنُ مَاجَهْ وَغَيْرُهُ","gist":"إِذَا لَمْ تَشْغَلْنَا الدُّنْيَا عَنِ الْآخِرَةِ أَحَبَّنَا اللَّهُ، وَإِذَا لَمْ نَطْمَعْ فِي مَا عِنْدَ النَّاسِ أَحَبَّنَا النَّاسُ."},{"id":"n32","n":32,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"لَا ضَرَرَ وَلَا ضِرَارَ","short":"لَا نُؤْذِي أَنْفُسَنَا وَلَا غَيْرَنَا","narr":"أَبُو سَعِيدٍ الْخُدْرِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الْخُدْرِيّ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:","text":"لَا ضَرَرَ وَلَا ضِرَارَ","extra":"","src":"رَوَاهُ ابْنُ مَاجَهْ وَالدَّارَقُطْنِيُّ وَغَيْرُهُمَا","gist":"لَا يَجُوزُ أَنْ نَضُرَّ أَنْفُسَنَا، وَلَا أَنْ نَضُرَّ غَيْرَنَا، وَلَا أَنْ نَرُدَّ الْأَذَى بِأَذًى أَكْبَرَ مِنْهُ."},{"id":"n33","n":33,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْبَيِّنَةُ عَلَى الْمُدَّعِي","short":"الْعَدْلُ بَيْنَ النَّاسِ","narr":"عَبْدُ اللَّهِ بْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:","text":"لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى رِجَالٌ أَمْوَالَ قَوْمٍ وَدِمَاءَهُمْ، لَكِنَّ الْبَيِّنَةَ عَلَى الْمُدَّعِي، وَالْيَمِينَ عَلَى مَنْ أَنْكَرَ","extra":"","src":"رَوَاهُ الْبَيْهَقِيُّ وَغَيْرُهُ","gist":"مَنِ ادَّعَى حَقًّا فَعَلَيْهِ أَنْ يُثْبِتَهُ بِدَلِيلٍ، وَمَنْ أَنْكَرَ فَعَلَيْهِ أَنْ يَحْلِفَ. وَهَذَا مِنْ عَدْلِ الْإِسْلَامِ."},{"id":"n34","n":34,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"تَغْيِيرُ الْمُنْكَرِ","short":"نُنْكِرُ الْمُنْكَرَ بِحَسَبِ قُدْرَتِنَا","narr":"أَبُو سَعِيدٍ الْخُدْرِيُّ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيّ رَضِيَ اللَّهُ عَنْهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ:","text":"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"إِذَا رَأَيْنَا خَطَأً نُغَيِّرُهُ بِالْيَدِ إِنْ قَدَرْنَا، وَإِلَّا بِالْكَلَامِ الطَّيِّبِ، وَإِلَّا فَبِالْقَلْبِ، وَهُوَ أَضْعَفُ الْإِيمَانِ. وَلِلْأَطْفَالِ يَكْفِي أَنْ يُخْبِرُوا الْكِبَارَ بِأَدَبٍ."},{"id":"n35","n":35,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْمُسْلِمُ أَخُو الْمُسْلِمِ","short":"نَتَعَامَلُ بِالْمَحَبَّةِ وَالْأُخُوَّةِ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ","text":"لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا، الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَكْذِبُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا، وَيُشِيرُ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ، بِحَسْبِ امْرِئٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ وَمَالُهُ وَعِرْضُهُ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"لَا نَحْسُدُ وَلَا نَكْذِبُ وَلَا نَظْلِمُ وَلَا نَحْتَقِرُ، وَنَكُونُ إِخْوَانًا مُتَحَابِّينَ. وَالتَّقْوَى مَحَلُّهَا الْقَلْبُ."},{"id":"n36","n":36,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"تَفْرِيجُ الْكُرُبَاتِ","short":"مَنْ سَاعَدَ النَّاسَ سَاعَدَهُ اللَّهُ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنْ النَّبِيِّ ﷺ قَالَ:","text":"مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ، يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِما سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاَللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ، وَيَتَدَارَسُونَهُ فِيمَا بَيْنَهُمْ؛ إِلَّا نَزَلَتْ عَلَيْهِمْ السَّكِينَةُ، وَغَشِيَتْهُمْ الرَّحْمَةُ، وَ حَفَّتهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ أَبَطْأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ","extra":"","src":"رَوَاهُ مُسْلِمٌ","gist":"مَنْ فَرَّجَ عَنْ مُؤْمِنٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ كُرْبَةً يَوْمَ الْقِيَامَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا دَامَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ."},{"id":"n37","n":37,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"الْحَسَنَاتُ وَالسَّيِّئَاتُ","short":"اللَّهُ يُضَاعِفُ الْحَسَنَاتِ","narr":"ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنْ رَسُولِ اللَّهِ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، قَالَ:","text":"إِنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ، فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً","extra":"","src":"رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ","gist":"مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ حَسَنَةً كَامِلَةً، فَإِنْ عَمِلَهَا كُتِبَتْ عَشْرَ حَسَنَاتٍ أَوْ أَكْثَرَ. وَمَنْ هَمَّ بِسَيِّئَةٍ وَتَرَكَهَا لِلَّهِ كُتِبَتْ لَهُ حَسَنَةً."},{"id":"n38","n":38,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"أَوْلِيَاءُ اللَّهِ","short":"نَتَقَرَّبُ إِلَى اللَّهِ بِالْفَرَائِضِ وَالنَّوَافِلِ","narr":"أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ","intro":"عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ إِنَّ اللَّهَ تَعَالَى قَالَ:","text":"مَنْ عَادَى لِي وَلِيًّا فَقَدِ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُهُ عَلَيْهِ، وَلَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَلَئِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنْ اسْتَعَاذَنِي لَأُعِيذَنَّهُ","extra":"","src":"رَوَاهُ الْبُخَارِيُّ","gist":"مَنْ أَدَّى الْفَرَائِضَ ثُمَّ أَكْثَرَ مِنَ النَّوَافِلِ أَحَبَّهُ اللَّهُ وَحَفِظَهُ وَأَجَابَ دُعَاءَهُ."},{"id":"n39","n":39,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"رَفْعُ الْخَطَأِ وَالنِّسْيَانِ","short":"اللَّهُ يَرْحَمُنَا فِي الْخَطَأِ وَالنِّسْيَانِ","narr":"ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ:","text":"إِنَّ اللَّهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ","extra":"","src":"رَوَاهُ ابْنُ مَاجَهْ وَالْبَيْهَقِيُّ وَغَيْرُهُمَا","gist":"مَنْ أَخْطَأَ دُونَ قَصْدٍ أَوْ نَسِيَ أَوْ أُجْبِرَ عَلَى أَمْرٍ فَلَا إِثْمَ عَلَيْهِ، وَهَذَا مِنْ رَحْمَةِ اللَّهِ بِنَا."},{"id":"n40","n":40,"grp":"الْأَرْبَعُونَ النَّوَوِيَّةُ","title":"كُنْ غَرِيبًا أَوْ عَابِرَ سَبِيلٍ","short":"لَا نَطْمَئِنُّ لِلدُّنْيَا وَنَسْتَعِدُّ لِلْآخِرَةِ","narr":"ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا","intro":"عَنْ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ ﷺ بِمَنْكِبِي، وَقَالَ:","text":"كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ","extra":"وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: إِذَا أَمْسَيْتَ فَلَا تَنْتَظِرْ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرْ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ، وَمِنْ حَيَاتِكَ لِمَوْتِكَ.","src":"رَوَاهُ الْبُخَارِيُّ","gist":"الدُّنْيَا مَكَانٌ نَمُرُّ بِهِ كَالْمُسَافِرِ، فَنَغْتَنِمُ صِحَّتَنَا وَحَيَاتَنَا فِي الطَّاعَةِ قَبْلَ أَنْ نَمْرَضَ أَوْ نَمُوتَ."}],"seerah":[{"id":"s-nasab","grp":"نَسَبُهُ وَأَهْلُهُ ﷺ","title":"نَسَبُ النَّبِيِّ ﷺ","sub":"مِنْ عَبْدِ اللَّهِ إِلَى عَدْنَانَ","paras":["هُوَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ الْمُطَّلِبِ بْنِ هَاشِمِ بْنِ عَبْدِ مَنَافٍ.","وَيَنْتَهِي نَسَبُهُ إِلَى عَدْنَانَ، وَعَدْنَانُ مِنْ ذُرِّيَّةِ نَبِيِّ اللَّهِ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ عَلَيْهِمَا السَّلَامُ.","وَهُوَ مِنْ قَبِيلَةِ قُرَيْشٍ، مِنْ بَنِي هَاشِمٍ. قَالَ ﷺ: إِنَّ اللَّهَ اصْطَفَى كِنَانَةَ مِنْ وَلَدِ إِسْمَاعِيلَ، وَاصْطَفَى قُرَيْشًا مِنْ كِنَانَةَ، وَاصْطَفَى مِنْ قُرَيْشٍ بَنِي هَاشِمٍ، وَاصْطَفَانِي مِنْ بَنِي هَاشِمٍ. رَوَاهُ مُسْلِمٌ.","أَبُوهُ عَبْدُ اللَّهِ، وَأُمُّهُ آمِنَةُ بِنْتُ وَهْبٍ، وَجَدُّهُ عَبْدُ الْمُطَّلِبِ سَيِّدُ قُرَيْشٍ."],"qs":[["إِلَى أَيِّ قَبِيلَةٍ يَنْتَمِي النَّبِيُّ ﷺ؟","قُرَيْشٌ","الْأَوْسُ","الْخَزْرَجُ"],["إِلَى أَيِّ نَبِيٍّ يَرْجِعُ نَسَبُ النَّبِيِّ ﷺ؟","إِسْمَاعِيلُ عَلَيْهِ السَّلَامُ","مُوسَى عَلَيْهِ السَّلَامُ","عِيسَى عَلَيْهِ السَّلَامُ"],["مَا اسْمُ جَدِّ النَّبِيِّ ﷺ الَّذِي كَانَ سَيِّدَ قُرَيْشٍ؟","عَبْدُ الْمُطَّلِبِ","أَبُو لَهَبٍ","أَبُو سُفْيَانَ"],["إِلَى أَيِّ بَطْنٍ مِنْ قُرَيْشٍ يَنْتَمِي النَّبِيُّ ﷺ؟","بَنُو هَاشِمٍ","بَنُو تَيْمٍ","بَنُو عَدِيٍّ"]]},{"id":"s-awlad","grp":"نَسَبُهُ وَأَهْلُهُ ﷺ","title":"أَوْلَادُ النَّبِيِّ ﷺ","sub":"سَبْعَةُ أَبْنَاءٍ وَبَنَاتٍ","paras":["رَزَقَ اللَّهُ نَبِيَّهُ ﷺ سَبْعَةَ أَوْلَادٍ: ثَلَاثَةَ أَبْنَاءٍ وَأَرْبَعَ بَنَاتٍ.","مِنَ السَّيِّدَةِ خَدِيجَةَ رَضِيَ اللَّهُ عَنْهَا: الْقَاسِمُ وَعَبْدُ اللَّهِ، وَزَيْنَبُ وَرُقَيَّةُ وَأُمُّ كُلْثُومٍ وَفَاطِمَةُ. وَمِنْ مَارِيَةَ الْقِبْطِيَّةِ رَضِيَ اللَّهُ عَنْهَا: إِبْرَاهِيمُ.","مَاتَ الْأَبْنَاءُ الثَّلَاثَةُ وَهُمْ صِغَارٌ، فَصَبَرَ النَّبِيُّ ﷺ وَرَضِيَ بِقَضَاءِ اللَّهِ.","وَأَمَّا الْبَنَاتُ: فَتَزَوَّجَتْ زَيْنَبُ مِنْ أَبِي الْعَاصِ بْنِ الرَّبِيعِ، وَتَزَوَّجَ عُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ رُقَيَّةَ ثُمَّ أُمَّ كُلْثُومٍ بَعْدَ وَفَاتِهَا، فَلُقِّبَ بِذِي النُّورَيْنِ، وَتَزَوَّجَ عَلِيُّ بْنُ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ فَاطِمَةَ.","وَمِنْ فَاطِمَةَ وَعَلِيٍّ: الْحَسَنُ وَالْحُسَيْنُ، حَفِيدَا النَّبِيِّ ﷺ. وَكُلُّ أَوْلَادِهِ تُوُفُّوا فِي حَيَاتِهِ ﷺ إِلَّا فَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا، فَقَدْ تُوُفِّيَتْ بَعْدَهُ بِنَحْوِ سِتَّةِ أَشْهُرٍ."],"qs":[["كَمْ عَدَدُ أَوْلَادِ النَّبِيِّ ﷺ؟","سَبْعَةٌ","خَمْسَةٌ","عَشَرَةٌ"],["مَنْ هِيَ أُمُّ أَكْثَرِ أَوْلَادِ النَّبِيِّ ﷺ؟","خَدِيجَةُ رَضِيَ اللَّهُ عَنْهَا","عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا","حَفْصَةُ رَضِيَ اللَّهُ عَنْهَا"],["مَنْ تَزَوَّجَ فَاطِمَةَ بِنْتَ النَّبِيِّ ﷺ؟","عَلِيُّ بْنُ أَبِي طَالِبٍ","عُثْمَانُ بْنُ عَفَّانَ","أَبُو بَكْرٍ الصِّدِّيقُ"],["مَنِ ابْنُ النَّبِيِّ ﷺ مِنْ مَارِيَةَ الْقِبْطِيَّةِ؟","إِبْرَاهِيمُ","الْقَاسِمُ","عَبْدُ اللَّهِ"],["لِمَاذَا لُقِّبَ عُثْمَانُ بْنُ عَفَّانَ بِذِي النُّورَيْنِ؟","لِأَنَّهُ تَزَوَّجَ بِنْتَيْنِ لِلنَّبِيِّ ﷺ","لِأَنَّهُ كَانَ شُجَاعًا فِي الْحَرْبِ","لِأَنَّهُ أَوَّلُ مَنْ أَسْلَمَ"],["مَنْ هُمَا حَفِيدَا النَّبِيِّ ﷺ مِنْ فَاطِمَةَ؟","الْحَسَنُ وَالْحُسَيْنُ","عَلِيٌّ وَعُثْمَانُ","حَمْزَةُ وَالْعَبَّاسُ"]]},{"id":"s-azwaj","grp":"نَسَبُهُ وَأَهْلُهُ ﷺ","title":"أَزْوَاجُ النَّبِيِّ ﷺ","sub":"أُمَّهَاتُ الْمُؤْمِنِينَ","paras":["زَوْجَاتُ النَّبِيِّ ﷺ هُنَّ أُمَّهَاتُ الْمُؤْمِنِينَ، قَالَ اللَّهُ تَعَالَى: ﴿وَأَزْوَاجُهُ أُمَّهَاتُهُمْ﴾","تَزَوَّجَ النَّبِيُّ ﷺ إِحْدَى عَشْرَةَ امْرَأَةً. أَوَّلُهُنَّ خَدِيجَةُ بِنْتُ خُوَيْلِدٍ، وَلَمْ يَتَزَوَّجْ عَلَيْهَا حَتَّى مَاتَتْ.","ثُمَّ تَزَوَّجَ: سَوْدَةَ بِنْتَ زَمْعَةَ، وَعَائِشَةَ بِنْتَ أَبِي بَكْرٍ الصِّدِّيقِ، وَحَفْصَةَ بِنْتَ عُمَرَ بْنِ الْخَطَّابِ، وَزَيْنَبَ بِنْتَ خُزَيْمَةَ، وَأُمَّ سَلَمَةَ.","ثُمَّ: زَيْنَبَ بِنْتَ جَحْشٍ، وَجُوَيْرِيَةَ بِنْتَ الْحَارِثِ، وَأُمَّ حَبِيبَةَ بِنْتَ أَبِي سُفْيَانَ، وَصَفِيَّةَ بِنْتَ حُيَيٍّ، وَمَيْمُونَةَ بِنْتَ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُنَّ جَمِيعًا.","مَاتَتْ خَدِيجَةُ وَزَيْنَبُ بِنْتُ خُزَيْمَةَ فِي حَيَاةِ النَّبِيِّ ﷺ، وَتُوُفِّيَ ﷺ عَنْ تِسْعِ نِسْوَةٍ.","كَانَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا مِنْ أَعْلَمِ النَّاسِ، رَوَتْ كَثِيرًا مِنَ الْأَحَادِيثِ وَعَلَّمَتِ الصَّحَابَةَ. وَكَانَتِ الصُّحُفُ الَّتِي جُمِعَ فِيهَا الْقُرْآنُ فِي عَهْدِ أَبِي بَكْرٍ عِنْدَ حَفْصَةَ رَضِيَ اللَّهُ عَنْهَا."],"qs":[["مَنْ أُولَى زَوْجَاتِ النَّبِيِّ ﷺ؟","خَدِيجَةُ بِنْتُ خُوَيْلِدٍ","عَائِشَةُ بِنْتُ أَبِي بَكْرٍ","حَفْصَةُ بِنْتُ عُمَرَ"],["مَا لَقَبُ زَوْجَاتِ النَّبِيِّ ﷺ؟","أُمَّهَاتُ الْمُؤْمِنِينَ","بَنَاتُ الْمُهَاجِرِينَ","أُمَّهَاتُ الْأَنْصَارِ"],["مَنْ هِيَ ابْنَةُ أَبِي بَكْرٍ الصِّدِّيقِ بَيْنَ زَوْجَاتِ النَّبِيِّ ﷺ؟","عَائِشَةُ","حَفْصَةُ","سَوْدَةُ"],["مَنْ هِيَ ابْنَةُ عُمَرَ بْنِ الْخَطَّابِ بَيْنَ زَوْجَاتِ النَّبِيِّ ﷺ؟","حَفْصَةُ","عَائِشَةُ","مَيْمُونَةُ"],["كَمْ عَدَدُ الزَّوْجَاتِ اللَّاتِي تَزَوَّجَهُنَّ النَّبِيُّ ﷺ؟","إِحْدَى عَشْرَةَ","أَرْبَعٌ","سَبْعٌ"]]},{"id":"s-quranm","grp":"مُعْجِزَاتُهُ ﷺ","title":"الْقُرْآنُ الْمُعْجِزَةُ الْكُبْرَى","sub":"مُعْجِزَةٌ بَاقِيَةٌ","paras":["كُلُّ نَبِيٍّ أَيَّدَهُ اللَّهُ بِمُعْجِزَةٍ، وَالْمُعْجِزَةُ أَمْرٌ عَجِيبٌ يَفْعَلُهُ اللَّهُ عَلَى يَدِ نَبِيِّهِ لِيَعْلَمَ النَّاسُ أَنَّهُ صَادِقٌ.","وَأَعْظَمُ مُعْجِزَاتِ نَبِيِّنَا مُحَمَّدٍ ﷺ هِيَ الْقُرْآنُ الْكَرِيمُ، وَهُوَ بَاقٍ إِلَى يَوْمِ الْقِيَامَةِ.","تَحَدَّى اللَّهُ الْعَرَبَ، وَهُمْ أَهْلُ الْفَصَاحَةِ وَالْبَلَاغَةِ، أَنْ يَأْتُوا بِمِثْلِهِ فَعَجَزُوا.","وَوَعَدَ اللَّهُ بِحِفْظِهِ مِنَ التَّغْيِيرِ، فَقَالَ: ﴿إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ﴾"],"qs":[["مَا أَعْظَمُ مُعْجِزَاتِ نَبِيِّنَا مُحَمَّدٍ ﷺ؟","الْقُرْآنُ الْكَرِيمُ","انْشِقَاقُ الْقَمَرِ","نَبْعُ الْمَاءِ"],["مَا الْمُعْجِزَةُ؟","أَمْرٌ عَجِيبٌ يُؤَيِّدُ اللَّهُ بِهِ نَبِيَّهُ","لُعْبَةٌ يَفْعَلُهَا السَّاحِرُ","حَدَثٌ يَتَكَرَّرُ كُلَّ يَوْمٍ"],["مَنْ وَعَدَ بِحِفْظِ الْقُرْآنِ مِنَ التَّغْيِيرِ؟","اللَّهُ تَعَالَى","الْمُلُوكُ","التُّجَّارُ"]]},{"id":"s-isra","grp":"مُعْجِزَاتُهُ ﷺ","title":"الْإِسْرَاءُ وَالْمِعْرَاجُ","sub":"رِحْلَةٌ فِي لَيْلَةٍ","paras":["فِي لَيْلَةٍ مِنَ اللَّيَالِي أَسْرَى اللَّهُ بِنَبِيِّهِ ﷺ مِنَ الْمَسْجِدِ الْحَرَامِ فِي مَكَّةَ إِلَى الْمَسْجِدِ الْأَقْصَى فِي بَيْتِ الْمَقْدِسِ.","قَالَ اللَّهُ تَعَالَى: ﴿سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾","ثُمَّ عُرِجَ بِهِ إِلَى السَّمَاوَاتِ الْعُلَا، وَرَأَى مِنْ آيَاتِ اللَّهِ الْعَظِيمَةِ، وَوَصَلَ إِلَى سِدْرَةِ الْمُنْتَهَى.","وَفِي هَذِهِ الرِّحْلَةِ فَرَضَ اللَّهُ عَلَيْنَا الصَّلَوَاتِ الْخَمْسَ، وَكَانَتْ تَكْرِيمًا مِنَ اللَّهِ لِنَبِيِّهِ ﷺ."],"qs":[["إِلَى أَيِّ مَسْجِدٍ أُسْرِيَ بِالنَّبِيِّ ﷺ؟","الْمَسْجِدُ الْأَقْصَى","مَسْجِدُ قُبَاءٍ","الْمَسْجِدُ النَّبَوِيُّ"],["مِنْ أَيِّ مَسْجِدٍ بَدَأَتْ رِحْلَةُ الْإِسْرَاءِ؟","الْمَسْجِدُ الْحَرَامُ","الْمَسْجِدُ الْأَقْصَى","مَسْجِدُ قُبَاءٍ"],["مَاذَا فَرَضَ اللَّهُ فِي رِحْلَةِ الْإِسْرَاءِ وَالْمِعْرَاجِ؟","الصَّلَوَاتِ الْخَمْسَ","صِيَامَ رَمَضَانَ","الزَّكَاةَ"],["كَمْ صَلَاةً نُصَلِّي فِي الْيَوْمِ وَاللَّيْلَةِ؟","خَمْسَ صَلَوَاتٍ","ثَلَاثَ صَلَوَاتٍ","سَبْعَ صَلَوَاتٍ"]]},{"id":"s-qamar","grp":"مُعْجِزَاتُهُ ﷺ","title":"انْشِقَاقُ الْقَمَرِ","sub":"آيَةٌ فِي السَّمَاءِ","paras":["طَلَبَ كُفَّارُ مَكَّةَ مِنَ النَّبِيِّ ﷺ أَنْ يُرِيَهُمْ آيَةً.","فَأَرَاهُمُ اللَّهُ الْقَمَرَ وَقَدِ انْشَقَّ فِرْقَتَيْنِ: فِرْقَةٌ فَوْقَ الْجَبَلِ وَفِرْقَةٌ دُونَهُ، فَقَالَ النَّبِيُّ ﷺ: اشْهَدُوا.","وَقَدْ ذَكَرَ اللَّهُ ذَلِكَ فِي سُورَةِ الْقَمَرِ: ﴿اقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ﴾","وَمَعَ هَذِهِ الْآيَةِ الْعَظِيمَةِ لَمْ يُؤْمِنْ أَكْثَرُهُمْ وَقَالُوا: سِحْرٌ."],"qs":[["مَاذَا حَدَثَ لِلْقَمَرِ بِمُعْجِزَةٍ مِنَ النَّبِيِّ ﷺ؟","انْشَقَّ فِرْقَتَيْنِ","اخْتَفَى","صَارَ أَحْمَرَ"],["فِي أَيِّ سُورَةٍ ذُكِرَ انْشِقَاقُ الْقَمَرِ؟","سُورَةُ الْقَمَرِ","سُورَةُ الشَّمْسِ","سُورَةُ النَّجْمِ"],["مَاذَا طَلَبَ كُفَّارُ مَكَّةَ مِنَ النَّبِيِّ ﷺ؟","أَنْ يُرِيَهُمْ آيَةً","أَنْ يُعْطِيَهُمُ الْمَالَ","أَنْ يَتْرُكَ مَكَّةَ"]]},{"id":"s-maa","grp":"مُعْجِزَاتُهُ ﷺ","title":"نَبْعُ الْمَاءِ مِنْ بَيْنِ أَصَابِعِهِ","sub":"يَوْمَ الْحُدَيْبِيَةِ","paras":["فِي يَوْمِ الْحُدَيْبِيَةِ عَطِشَ الصَّحَابَةُ رَضِيَ اللَّهُ عَنْهُمْ، وَلَمْ يَكُنْ عِنْدَهُمْ إِلَّا إِنَاءٌ صَغِيرٌ فِيهِ قَلِيلٌ مِنَ الْمَاءِ بَيْنَ يَدَيِ النَّبِيِّ ﷺ.","فَوَضَعَ النَّبِيُّ ﷺ يَدَهُ فِي الْإِنَاءِ، فَجَعَلَ الْمَاءُ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ كَأَنَّهُ عُيُونٌ.","فَشَرِبُوا وَتَوَضَّؤُوا جَمِيعًا، وَكَانُوا أَكْثَرَ مِنْ أَلْفٍ. وَالْقِصَّةُ فِي صَحِيحِ الْبُخَارِيِّ عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا."],"qs":[["مِنْ أَيْنَ نَبَعَ الْمَاءُ فِي هَذِهِ الْمُعْجِزَةِ؟","مِنْ بَيْنِ أَصَابِعِ النَّبِيِّ ﷺ","مِنْ بِئْرٍ قَدِيمَةٍ","مِنْ جَبَلٍ قَرِيبٍ"],["فِي أَيِّ يَوْمٍ حَدَثَتْ هَذِهِ الْقِصَّةِ؟","يَوْمَ الْحُدَيْبِيَةِ","يَوْمَ بَدْرٍ","يَوْمَ الْفَتْحِ"],["لِمَاذَا احْتَاجَ الصَّحَابَةُ إِلَى الْمَاءِ؟","لِأَنَّهُمْ عَطِشُوا","لِيَسْقُوا الْأَشْجَارَ","لِيَغْسِلُوا الثِّيَابَ"]]},{"id":"s-jidh","grp":"مُعْجِزَاتُهُ ﷺ","title":"حَنِينُ الْجِذْعِ","sub":"جِذْعٌ يَبْكِي","paras":["كَانَ النَّبِيُّ ﷺ يَخْطُبُ يَوْمَ الْجُمُعَةِ وَهُوَ وَاقِفٌ بِجَانِبِ جِذْعِ نَخْلَةٍ فِي الْمَسْجِدِ.","فَلَمَّا صُنِعَ لَهُ مِنْبَرٌ وَصَعِدَ عَلَيْهِ، سَمِعَ النَّاسُ مِنَ الْجِذْعِ صَوْتًا كَصَوْتِ النَّاقَةِ الْحَامِلِ.","فَنَزَلَ النَّبِيُّ ﷺ وَضَمَّهُ إِلَيْهِ فَسَكَنَ. وَقَالَ الصَّحَابَةُ إِنَّهُ كَانَ يَبْكِي عَلَى الذِّكْرِ الَّذِي كَانَ يَسْمَعُهُ عِنْدَهُ. رَوَاهُ الْبُخَارِيُّ."],"qs":[["مَا الَّذِي حَنَّ لِفِرَاقِ النَّبِيِّ ﷺ؟","جِذْعُ النَّخْلَةِ","بَابُ الْمَسْجِدِ","سِرَاجُ الْمَسْجِدِ"],["مَاذَا فَعَلَ النَّبِيُّ ﷺ لِلْجِذْعِ حِينَ حَنَّ؟","ضَمَّهُ إِلَيْهِ فَسَكَنَ","تَرَكَهُ يَبْكِي","أَبْعَدَهُ عَنِ الْمَسْجِدِ"],["عَلَى أَيِّ شَيْءٍ صَعِدَ النَّبِيُّ ﷺ لِيَخْطُبَ بَعْدَ الْجِذْعِ؟","الْمِنْبَرِ","السَّطْحِ","الْجَبَلِ"]]},{"id":"s-taam","grp":"مُعْجِزَاتُهُ ﷺ","title":"الطَّعَامُ الْقَلِيلُ يَكْفِي الْكَثِيرِينَ","sub":"فِي غَزْوَةِ الْخَنْدَقِ","paras":["فِي غَزْوَةِ الْخَنْدَقِ كَانَ الصَّحَابَةُ يَحْفِرُونَ الْخَنْدَقَ وَيُعَانُونَ مِنَ الْجُوعِ.","فَذَبَحَ جَابِرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا شَاةً صَغِيرَةً، وَطَحَنَتْ زَوْجَتُهُ قَلِيلًا مِنَ الشَّعِيرِ، ثُمَّ دَعَا النَّبِيَّ ﷺ.","فَدَعَا النَّبِيُّ ﷺ أَهْلَ الْخَنْدَقِ جَمِيعًا، وَكَانُوا نَحْوَ أَلْفٍ، وَبَارَكَ اللَّهُ فِي الطَّعَامِ، فَأَكَلُوا حَتَّى شَبِعُوا وَبَقِيَ الطَّعَامُ كَمَا كَانَ. رَوَاهُ الْبُخَارِيُّ."],"qs":[["فِي أَيِّ غَزْوَةٍ حَدَثَتْ هَذِهِ الْقِصَّةُ؟","غَزْوَةِ الْخَنْدَقِ","غَزْوَةِ بَدْرٍ","غَزْوَةِ تَبُوكَ"],["مَنِ الصَّحَابِيُّ الَّذِي دَعَا النَّبِيَّ ﷺ إِلَى طَعَامِهِ؟","جَابِرُ بْنُ عَبْدِ اللَّهِ","أَبُو هُرَيْرَةَ","أَنَسُ بْنُ مَالِكٍ"],["مَاذَا حَدَثَ لِلطَّعَامِ الْقَلِيلِ؟","بَارَكَ اللَّهُ فِيهِ فَكَفَى الْجَمِيعَ","فَسَدَ","نَفِدَ سَرِيعًا"]]},{"id":"s-ali","grp":"مُعْجِزَاتُهُ ﷺ","title":"شِفَاءُ عَيْنَيْ عَلِيٍّ","sub":"فِي غَزْوَةِ خَيْبَرَ","paras":["فِي غَزْوَةِ خَيْبَرَ قَالَ النَّبِيُّ ﷺ: لَأُعْطِيَنَّ الرَّايَةَ غَدًا رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ.","فَبَاتَ النَّاسُ يَتَسَاءَلُونَ: مَنْ سَيُعْطَاهَا؟ وَفِي الصَّبَاحِ دَعَا النَّبِيُّ ﷺ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ يَشْتَكِي عَيْنَيْهِ.","فَوَضَعَ النَّبِيُّ ﷺ مِنْ رِيقِهِ فِي عَيْنَيْهِ وَدَعَا لَهُ، فَشُفِيَ حَتَّى كَأَنْ لَمْ يَكُنْ بِهِ وَجَعٌ، وَأَعْطَاهُ الرَّايَةَ. رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ."],"qs":[["مَنْ أَعْطَاهُ النَّبِيُّ ﷺ الرَّايَةَ يَوْمَ خَيْبَرَ؟","عَلِيُّ بْنُ أَبِي طَالِبٍ","عُمَرُ بْنُ الْخَطَّابِ","خَالِدُ بْنُ الْوَلِيدِ"],["مَاذَا حَدَثَ لِعَيْنَيْ عَلِيٍّ بَعْدَ دُعَاءِ النَّبِيِّ ﷺ؟","شُفِيَتَا","ازْدَادَ الْوَجَعُ","ضَعُفَ الْبَصَرُ"],["فِي أَيِّ غَزْوَةٍ حَدَثَتْ هَذِهِ الْقِصَّةُ؟","غَزْوَةِ خَيْبَرَ","غَزْوَةِ أُحُدٍ","غَزْوَةِ حُنَيْنٍ"]]}]};
